fn narrow(x:i64)->i16{x as i16}
fn line(d:&mut [i16;64],base:usize,k:usize,m:u32,n:u32,r:&[i16;12]){let mut t=[0i64;12];for j in 0..4{t[j]=d[base+k*j] as i64+d[base+k*(7-j)] as i64;t[7-j]=d[base+k*j] as i64-d[base+k*(7-j)] as i64}t[8]=t[0]+t[3];t[9]=t[0]-t[3];t[10]=t[1]+t[2];t[11]=t[1]-t[2];d[base]=narrow((t[8]+t[10])>>m);d[base+4*k]=narrow((t[8]-t[10])>>m);t[8]=(t[11]+t[9]) as i16 as i64*r[10] as i64;d[base+2*k]=narrow(t[8]+(((t[9]*r[9] as i64)>>n) as i16 as i64));d[base+6*k]=narrow(t[8]+(((t[11]*r[11] as i64)>>n) as i16 as i64));t[0]=(t[4]+t[7]) as i16 as i64*r[2] as i64;t[1]=(t[5]+t[6]) as i16 as i64*r[0] as i64;t[2]=t[4]+t[6];t[3]=t[5]+t[7];t[8]=(t[2]+t[3]) as i16 as i64*r[8] as i64;t[2]=t[2] as i16 as i64*r[1] as i64+t[8];t[3]=t[3] as i16 as i64*r[3] as i64+t[8];d[base+7*k]=narrow(((t[4]*r[4] as i64+t[0]+t[2]) as i16 as i64)>>n);d[base+5*k]=narrow(((t[5]*r[6] as i64+t[1]+t[3]) as i16 as i64)>>n);d[base+3*k]=narrow(((t[6]*r[5] as i64+t[1]+t[2]) as i16 as i64)>>n);d[base+k]=narrow(((t[7]*r[7] as i64+t[0]+t[3]) as i16 as i64)>>n);}
#[no_mangle] pub unsafe extern "C" fn edn_jpeg_dct(raw:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if raw.is_null()||n!=76{return -1}let v=unsafe{std::slice::from_raw_parts(raw,n)};let mut d=[0i16;64];let mut r=[0i16;12];for i in 0..64{if !(-8..=8).contains(&v[i]){return -1}d[i]=v[i] as i16}for i in 0..12{if !(-32..=31).contains(&v[64+i]){return -1}r[i]=v[64+i] as i16}if out.is_null()||cap<512{return -2}for row in 0..8{line(&mut d,row*8,1,0,13,&r)}for col in 0..8{line(&mut d,col,8,3,16,&r)}let o=unsafe{std::slice::from_raw_parts_mut(out,512)};for i in 0..64{o[8*i..8*i+8].copy_from_slice(&(d[i] as i64).to_le_bytes())}512}
